import{_ as e,c as t,o as i,a0 as a}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Modèle de journal d&#39;entraînement","description":"","frontmatter":{},"headers":[],"relativePath":"fr/diary-template.md","filePath":"fr/diary-template.md"}');const o=e({name:"fr/diary-template.md"},[["render",function(e,r,o,n,s,l){return i(),t("div",null,[...r[0]||(r[0]=[a('<h1 id="modele-de-journal-d-39-entrainement" tabindex="-1">Modèle de journal d&#39;entraînement <a class="header-anchor" href="#modele-de-journal-d-39-entrainement" aria-label="Permalink to &quot;Modèle de journal d&amp;#39;entraînement&quot;">​</a></h1><h2 id="comment-utiliser-ce-modele" tabindex="-1">Comment utiliser ce modèle <a class="header-anchor" href="#comment-utiliser-ce-modele" aria-label="Permalink to &quot;Comment utiliser ce modèle&quot;">​</a></h2><p>Un journal d&#39;entraînement est votre registre personnel de pratique, de progrès et d&#39;observations. Il vous aide à identifier ce qui fonctionne, à repérer les tendances et à accélérer votre progression. Copiez les sections ci-dessous dans le format de votre choix (Word, Google Docs, Excel, Google Sheets ou un bloc-notes).</p><div class="tip custom-block"><p class="custom-block-title">: Le pouvoir de la réflexion</p><p>Ce qui est mesuré s&#39;améliore. Ce sur quoi on réfléchit s&#39;acquiert. Un journal d&#39;entraînement transforme la pratique aléatoire en développement délibéré.</p></div><h2 id="modele-de-saisie-d-39-entrainement-quotidien" tabindex="-1">Modèle de saisie d&#39;entraînement quotidien <a class="header-anchor" href="#modele-de-saisie-d-39-entrainement-quotidien" aria-label="Permalink to &quot;Modèle de saisie d&amp;#39;entraînement quotidien&quot;">​</a></h2><h3 id="copiez-cette-section-pour-chaque-session-de-formation" tabindex="-1">Copiez cette section pour chaque session de formation <a class="header-anchor" href="#copiez-cette-section-pour-chaque-session-de-formation" aria-label="Permalink to &quot;Copiez cette section pour chaque session de formation&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Time:</strong> ________ to ________ <strong>Duration:</strong> ________ minutes <strong>Location:</strong> ________ <strong>Terrain:</strong> Hard / Medium / Soft / Mixed <strong>Weather:</strong> Sunny / Cloudy / Windy / Rain</p><h3 id="training-partners" tabindex="-1">Training Partners <a class="header-anchor" href="#training-partners" aria-label="Permalink to &quot;Training Partners&quot;">​</a></h3><ul><li></li><li></li><li></li></ul><h3 id="today-s-intention" tabindex="-1">Today&#39;s Intention <a class="header-anchor" href="#today-s-intention" aria-label="Permalink to &quot;Today&#39;s Intention&quot;">​</a></h3><p>(What was my main focus for this session?)</p><hr><h3 id="pratique-technique" tabindex="-1">Pratique technique <a class="header-anchor" href="#pratique-technique" aria-label="Permalink to &quot;Pratique technique&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Compétence travaillée</th><th>Répétitions/Temps</th><th>Taux de réussite</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Pointage</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Fusillade</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Lecture du terrain</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Sélection du plan</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="qu-39-est-ce-qui-a-bien-fonctionne" tabindex="-1">Qu&#39;est-ce qui a bien fonctionné ? <a class="header-anchor" href="#qu-39-est-ce-qui-a-bien-fonctionne" aria-label="Permalink to &quot;Qu&amp;#39;est-ce qui a bien fonctionné ?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="quels-sont-les-points-a-ameliorer" tabindex="-1">Quels sont les points à améliorer ? <a class="header-anchor" href="#quels-sont-les-points-a-ameliorer" aria-label="Permalink to &quot;Quels sont les points à améliorer ?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="point-cle" tabindex="-1">Point clé <a class="header-anchor" href="#point-cle" aria-label="Permalink to &quot;Point clé&quot;">​</a></h3><p>(Un des principaux enseignements d&#39;aujourd&#39;hui)</p><hr><h3 id="mental-game" tabindex="-1">Mental Game <a class="header-anchor" href="#mental-game" aria-label="Permalink to &quot;Mental Game&quot;">​</a></h3><p><strong>Energy Level (1-10):</strong> _____ <strong>Focus Quality (1-10):</strong> _____ <strong>Confidence (1-10):</strong> _____</p><p><strong>Mental Challenges Today:</strong></p><p><strong>How I Handled Them:</strong></p><p><strong>Mental Technique Practiced:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Other: ________</li></ul><hr><h3 id="etat-physique" tabindex="-1">État physique <a class="header-anchor" href="#etat-physique" aria-label="Permalink to &quot;État physique&quot;">​</a></h3><p><strong>Sensations corporelles (1-10) :</strong> _____ <strong>Toute douleur ou gêne :</strong> _____ <strong>Niveau de fatigue (1-10) :</strong> _____</p><p><strong>Remarques physiques :</strong></p><hr><h3 id="tomorrow-s-focus" tabindex="-1">Tomorrow&#39;s Focus <a class="header-anchor" href="#tomorrow-s-focus" aria-label="Permalink to &quot;Tomorrow&#39;s Focus&quot;">​</a></h3><p>(Based on today, what will I work on next session?)</p><hr><h2 id="modele-d-39-inscription-a-une-competition-un-match" tabindex="-1">Modèle d&#39;inscription à une compétition/un match <a class="header-anchor" href="#modele-d-39-inscription-a-une-competition-un-match" aria-label="Permalink to &quot;Modèle d&amp;#39;inscription à une compétition/un match&quot;">​</a></h2><h3 id="copiez-cette-section-pour-chaque-competition" tabindex="-1">Copiez cette section pour chaque compétition <a class="header-anchor" href="#copiez-cette-section-pour-chaque-competition" aria-label="Permalink to &quot;Copiez cette section pour chaque compétition&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Tournament:</strong> ________ <strong>Format:</strong> Triples / Doubles / Singles <strong>Team:</strong> ________</p><h3 id="pre-competition" tabindex="-1">Pre-Competition <a class="header-anchor" href="#pre-competition" aria-label="Permalink to &quot;Pre-Competition&quot;">​</a></h3><p><strong>Sleep Quality (1-10):</strong> _____ <strong>Nutrition:</strong> _____ <strong>Mental State (1-10):</strong> _____ <strong>Physical Warm-up:</strong> Yes / No <strong>Mental Warm-up:</strong> Yes / No</p><hr><h3 id="resultats-du-match" tabindex="-1">Résultats du match <a class="header-anchor" href="#resultats-du-match" aria-label="Permalink to &quot;Résultats du match&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tour</th><th>Adversaire</th><th>Score</th><th>Résultat</th><th>Moments clés</th></tr></thead><tbody><tr><td><strong>1</strong></td><td></td><td></td><td>V / D</td><td></td></tr><tr><td><strong>2</strong></td><td></td><td></td><td>V / D</td><td></td></tr><tr><td><strong>3</strong></td><td></td><td></td><td>V / D</td><td></td></tr><tr><td><strong>4</strong></td><td></td><td></td><td>V / D</td><td></td></tr></tbody></table><p><strong>Classement final :</strong> _____</p><hr><h3 id="performance-analysis" tabindex="-1">Performance Analysis <a class="header-anchor" href="#performance-analysis" aria-label="Permalink to &quot;Performance Analysis&quot;">​</a></h3><p><strong>Technical Performance (1-10):</strong> _____ <strong>Mental Performance (1-10):</strong> _____ <strong>Tactical Decisions (1-10):</strong> _____ <strong>Team Communication (1-10):</strong> _____</p><h3 id="what-i-did-well" tabindex="-1">What I Did Well <a class="header-anchor" href="#what-i-did-well" aria-label="Permalink to &quot;What I Did Well&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="what-cost-me-points" tabindex="-1">What Cost Me Points <a class="header-anchor" href="#what-cost-me-points" aria-label="Permalink to &quot;What Cost Me Points&quot;">​</a></h3><ol><li></li><li></li></ol><h2 id="monthly-summary-template" tabindex="-1">Monthly Summary Template <a class="header-anchor" href="#monthly-summary-template" aria-label="Permalink to &quot;Monthly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Mois:</strong> ________ <strong>Année:</strong> ________</p><h3 id="statistiques-mensuelles" tabindex="-1">Statistiques mensuelles <a class="header-anchor" href="#statistiques-mensuelles" aria-label="Permalink to &quot;Statistiques mensuelles&quot;">​</a></h3><p><strong>Nombre total d&#39;heures de formation :</strong> _____ <strong>Nombre total de séances :</strong> _____ <strong>Concours auxquels j&#39;ai participé :</strong> _____ <strong>Taux de victoire :</strong> _____%</p><h3 id="progres-techniques" tabindex="-1">Progrès techniques <a class="header-anchor" href="#progres-techniques" aria-label="Permalink to &quot;Progrès techniques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Compétence</th><th>Début du mois</th><th>Fin du mois</th><th>Amélioration</th></tr></thead><tbody><tr><td><strong>Précision de pointage</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Régularité des tirs</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Adaptation au terrain</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Sélection du plan</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="progres-mentaux" tabindex="-1">Progrès mentaux <a class="header-anchor" href="#progres-mentaux" aria-label="Permalink to &quot;Progrès mentaux&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Zone</th><th>Début du mois</th><th>Fin du mois</th><th>Amélioration</th></tr></thead><tbody><tr><td><strong>Gestion de la pression</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Focus qualité</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Confiance</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Utilisation du coach interne</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="faits-saillants-du-mois" tabindex="-1">Faits saillants du mois <a class="header-anchor" href="#faits-saillants-du-mois" aria-label="Permalink to &quot;Faits saillants du mois&quot;">​</a></h3><p><strong>Meilleure séance de formation :</strong></p><p><strong>Meilleure performance en compétition :</strong></p><p><strong>Percée majeure :</strong></p><p><strong>Apprentissage le plus précieux :</strong></p><h3 id="defis-surmontes" tabindex="-1">Défis surmontés <a class="header-anchor" href="#defis-surmontes" aria-label="Permalink to &quot;Défis surmontés&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="defis-en-cours" tabindex="-1">Défis en cours <a class="header-anchor" href="#defis-en-cours" aria-label="Permalink to &quot;Défis en cours&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="priorites-du-mois-prochain" tabindex="-1">Priorités du mois prochain <a class="header-anchor" href="#priorites-du-mois-prochain" aria-label="Permalink to &quot;Priorités du mois prochain&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr><h2 id="specific-practice-tracking-templates" tabindex="-1">Specific Practice Tracking Templates <a class="header-anchor" href="#specific-practice-tracking-templates" aria-label="Permalink to &quot;Specific Practice Tracking Templates&quot;">​</a></h2><h3 id="pointing-practice-log" tabindex="-1">Pointing Practice Log <a class="header-anchor" href="#pointing-practice-log" aria-label="Permalink to &quot;Pointing Practice Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Distance</th><th>Terrain</th><th>Attempts</th><th>Within 10cm</th><th>Within 20cm</th><th>Within 50cm</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions:</strong></p><ul><li>Track pointing accuracy at different distances (6m, 7m, 8m, 9m, 10m)</li><li>Record terrain type (hard, medium, soft)</li><li>Count successes in each distance range</li><li>Calculate success rate over time</li></ul><hr><h3 id="carnet-d-39-entrainement-au-tir" tabindex="-1">Carnet d&#39;entraînement au tir <a class="header-anchor" href="#carnet-d-39-entrainement-au-tir" aria-label="Permalink to &quot;Carnet d&amp;#39;entraînement au tir&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Type de cible</th><th>Distance</th><th>Tentatives</th><th>Coups directs</th><th>Carreau</th><th>Déplacement</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Types de cibles :</strong></p><ul><li>Balle statique</li><li>Balle contre le cochonnet</li><li>Balle en grappe</li><li>Cible mobile (avancée)</li></ul><hr><h3 id="mental-training-log" tabindex="-1">Mental Training Log <a class="header-anchor" href="#mental-training-log" aria-label="Permalink to &quot;Mental Training Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Technique Practiced</th><th>Duration</th><th>Situation</th><th>Effectiveness (1-10)</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Techniques:</strong></p><ul><li>3-Breath Reset</li><li>Inner Coach Reframe</li><li>Visualization</li><li>Mindfulness Practice</li><li>Pre-shot Routine</li><li>Pressure Simulation</li></ul><hr><h2 id="saisie-quotidienne-rapide-simplifiee" tabindex="-1">Saisie quotidienne rapide (simplifiée) <a class="header-anchor" href="#saisie-quotidienne-rapide-simplifiee" aria-label="Permalink to &quot;Saisie quotidienne rapide (simplifiée)&quot;">​</a></h2><h3 id="pour-les-jours-charges-copiez-ce-modele-minimaliste" tabindex="-1">Pour les jours chargés - Copiez ce modèle minimaliste <a class="header-anchor" href="#pour-les-jours-charges-copiez-ce-modele-minimaliste" aria-label="Permalink to &quot;Pour les jours chargés - Copiez ce modèle minimaliste&quot;">​</a></h3><hr><p><strong>Date:</strong> ________</p><p><strong>Trained:</strong> Yes / No <strong>Duration:</strong> _____ min <strong>Focus:</strong> ________ <strong>Energy (1-10):</strong> _____ <strong>Quality (1-10):</strong> _____</p><p><strong>One Win:</strong></p><p><strong>One Learning:</strong></p><p><strong>Tomorrow&#39;s Focus:</strong></p><hr><h2 id="sujets-de-reflexion" tabindex="-1">Sujets de réflexion <a class="header-anchor" href="#sujets-de-reflexion" aria-label="Permalink to &quot;Sujets de réflexion&quot;">​</a></h2><p>Utilisez ces suggestions pour approfondir vos entrées de journal :</p><h3 id="apres-l-39-entrainement" tabindex="-1">Après l&#39;entraînement <a class="header-anchor" href="#apres-l-39-entrainement" aria-label="Permalink to &quot;Après l&amp;#39;entraînement&quot;">​</a></h3><ol><li>Qu&#39;est-ce qui m&#39;a surpris aujourd&#39;hui ?</li><li>À quel moment me suis-je senti le plus en confiance ?</li><li>Quand ai-je rencontré des difficultés ? Pourquoi ?</li><li>Que ferais-je différemment ?</li><li>De quoi suis-je reconnaissant(e) suite à cette séance ?</li></ol><h3 id="apres-la-competition" tabindex="-1">Après la compétition <a class="header-anchor" href="#apres-la-competition" aria-label="Permalink to &quot;Après la compétition&quot;">​</a></h3><ol><li>Qu&#39;ai-je appris sur moi-même aujourd&#39;hui ?</li><li>Comment ai-je géré la pression ?</li><li>Que dirait mon coach intérieur de ma performance ?</li><li>Que vais-je pratiquer différemment à partir d&#39;aujourd&#39;hui ?</li><li>De quoi suis-je fier, quel que soit le résultat ?</li></ol><h3 id="reflexion-hebdomadaire" tabindex="-1">Réflexion hebdomadaire <a class="header-anchor" href="#reflexion-hebdomadaire" aria-label="Permalink to &quot;Réflexion hebdomadaire&quot;">​</a></h3><ol><li>Quel schéma observe-je dans ma pratique ?</li><li>Est-ce que je m&#39;entraîne sur les points qui me posent problème en compétition ?</li><li>Mon jeu mental s&#39;améliore-t-il ?</li><li>Est-ce que j&#39;apprécie le processus ?</li><li>Que faut-il changer la semaine prochaine ?</li></ol><h3 id="reflexion-mensuelle" tabindex="-1">Réflexion mensuelle <a class="header-anchor" href="#reflexion-mensuelle" aria-label="Permalink to &quot;Réflexion mensuelle&quot;">​</a></h3><ol><li>Suis-je plus proche de mes objectifs que le mois dernier ?</li><li>Qu&#39;est-ce qui fonctionne dans mon approche de formation ?</li><li>Qu&#39;est-ce qui ne fonctionne pas ?</li><li>Dois-je revoir mes objectifs ?</li><li>Que veux-je retenir de ce mois-ci ?</li></ol><hr><h2 id="tips-for-effective-diary-keeping" tabindex="-1">Tips for Effective Diary Keeping <a class="header-anchor" href="#tips-for-effective-diary-keeping" aria-label="Permalink to &quot;Tips for Effective Diary Keeping&quot;">​</a></h2><h3 id="_1-write-immediately-after-training" tabindex="-1">1. Write Immediately After Training <a class="header-anchor" href="#_1-write-immediately-after-training" aria-label="Permalink to &quot;1. Write Immediately After Training&quot;">​</a></h3><p><strong>Why:</strong> Details are fresh, emotions are real, insights are clear</p><p><strong>How:</strong> Keep diary in your bag, set 10 minutes aside after each session</p><h3 id="_2-be-honest-not-perfect" tabindex="-1">2. Be Honest, Not Perfect <a class="header-anchor" href="#_2-be-honest-not-perfect" aria-label="Permalink to &quot;2. Be Honest, Not Perfect&quot;">​</a></h3><p><strong>Don&#39;t:</strong> Write what you think you should write <strong>Do:</strong> Write what actually happened and how you really felt</p><h3 id="_3-focus-on-process-not-just-results" tabindex="-1">3. Focus on Process, Not Just Results <a class="header-anchor" href="#_3-focus-on-process-not-just-results" aria-label="Permalink to &quot;3. Focus on Process, Not Just Results&quot;">​</a></h3><p><strong>Don&#39;t:</strong> &quot;Missed 7 out of 10 shots - terrible&quot; <strong>Do:</strong> &quot;Missed 7 out of 10 shots - noticed I was rushing my routine, will slow down next time&quot;</p><h3 id="_4-look-for-patterns" tabindex="-1">4. Look for Patterns <a class="header-anchor" href="#_4-look-for-patterns" aria-label="Permalink to &quot;4. Look for Patterns&quot;">​</a></h3><p>Review your diary weekly to spot:</p><ul><li>Recurring technical issues</li><li>Mental game patterns</li><li>Energy/performance correlations</li><li>What conditions you perform best in</li></ul><h3 id="_5-celebrate-progress" tabindex="-1">5. Celebrate Progress <a class="header-anchor" href="#_5-celebrate-progress" aria-label="Permalink to &quot;5. Celebrate Progress&quot;">​</a></h3><p><strong>Every month:</strong> Read entries from 3 months ago <strong>Notice:</strong> How much you&#39;ve improved <strong>Acknowledge:</strong> The work you&#39;ve put in</p><hr><h2 id="agenda-numerique-vs-agenda-papier" tabindex="-1">Agenda numérique vs. agenda papier <a class="header-anchor" href="#agenda-numerique-vs-agenda-papier" aria-label="Permalink to &quot;Agenda numérique vs. agenda papier&quot;">​</a></h2><h3 id="outils-numeriques-google-docs-sheets-notion-applications" tabindex="-1">Outils numériques (Google Docs/Sheets, Notion, Applications) <a class="header-anchor" href="#outils-numeriques-google-docs-sheets-notion-applications" aria-label="Permalink to &quot;Outils numériques (Google Docs/Sheets, Notion, Applications)&quot;">​</a></h3><p><strong>Avantages :</strong></p><ul><li>Recherche facile des entrées précédentes</li><li>Possibilité d&#39;ajouter des photos/vidéos</li><li>Horodatage automatique</li><li>Peut être partagé avec l&#39;entraîneur</li><li>Toujours joignable par téléphone</li></ul><p><strong>Inconvénients :</strong></p><ul><li>Temps passé devant un écran</li><li>Peut sembler impersonnel</li><li>Distractions par rapport aux notifications</li></ul><p><strong>Idéal pour :</strong> Suivi statistique détaillé, analyse des tendances à long terme</p><h3 id="papier-cahier-modeles-imprimes" tabindex="-1">Papier (cahier, modèles imprimés) <a class="header-anchor" href="#papier-cahier-modeles-imprimes" aria-label="Permalink to &quot;Papier (cahier, modèles imprimés)&quot;">​</a></h3><p><strong>Avantages :</strong></p><ul><li>Contact tactile et personnel</li><li>Aucune distraction</li><li>Des schémas faciles à dessiner</li><li>Rituel satisfaisant</li><li>Meilleur pour la réflexion</li></ul><p><strong>Inconvénients :</strong></p><ul><li>Peut perdre son cahier</li><li>Il est difficile de rechercher les anciennes entrées.</li><li>Difficile à partager</li></ul><p><strong>Idéal pour :</strong> Réflexions quotidiennes, notes prises immédiatement après l&#39;entraînement</p><p><strong>Recommandation :</strong> Approche hybride : format papier pour les entrées quotidiennes, format numérique pour les synthèses mensuelles et les statistiques.</p><hr><h2 id="sample-entries" tabindex="-1">Sample Entries <a class="header-anchor" href="#sample-entries" aria-label="Permalink to &quot;Sample Entries&quot;">​</a></h2><h3 id="example-good-training-entry" tabindex="-1">Example: Good Training Entry <a class="header-anchor" href="#example-good-training-entry" aria-label="Permalink to &quot;Example: Good Training Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 15, 2024 <strong>Duration:</strong> 90 minutes <strong>Location:</strong> Club terrain <strong>Terrain:</strong> Hard <strong>Weather:</strong> Sunny, light wind</p><p><strong>Today&#39;s Intention:</strong> Improve pointing accuracy at 8m</p><p><strong>Technical Practice:</strong></p><ul><li>Pointing at 8m: 30 attempts, 18 within 20cm (60%)</li><li>Noticed I&#39;m more accurate when I take 3 breaths before throwing</li><li>Struggled when wind picked up - need to adjust for wind better</li></ul><p><strong>What Worked Well:</strong></p><ol><li>Pre-shot routine was consistent</li><li>Stayed calm after misses</li><li>Adjusted grip for hard terrain</li></ol><p><strong>Key Insight:</strong> My accuracy drops when I rush. Slowing down by 2 seconds improves success rate significantly.</p><p><strong>Mental Game:</strong></p><ul><li>Energy: 8/10</li><li>Focus: 7/10</li><li>Used Inner Coach after 3 bad throws - helped me reset</li></ul><p><strong>Tomorrow&#39;s Focus:</strong> Practice pointing in windy conditions, maintain slow routine</p></details><h3 id="example-good-competition-entry" tabindex="-1">Example: Good Competition Entry <a class="header-anchor" href="#example-good-competition-entry" aria-label="Permalink to &quot;Example: Good Competition Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 20, 2024 <strong>Tournament:</strong> Regional Championship <strong>Format:</strong> Triples <strong>Final Placement:</strong> 5th of 16 teams</p><p><strong>Performance Analysis:</strong></p><ul><li>Technical: 7/10 - Pointing was solid, shooting was inconsistent</li><li>Mental: 8/10 - Stayed calm under pressure</li><li>Tactical: 6/10 - Made one bad decision in semi-final</li></ul><p><strong>Best Moment:</strong> Carreau in quarter-final to win 13-12</p><p><strong>Toughest Moment:</strong> Semi-final, 11-11, rushed a shot and missed badly</p><p><strong>Key Learning:</strong> When score is tight, I need to slow down even more, not speed up. My Inner Critic tried to take over (&quot;Don&#39;t mess this up!&quot;) but I caught it and used Inner Coach instead (&quot;You&#39;ve made this shot 100 times, trust your routine&quot;).</p><p><strong>For Next Competition:</strong> Practice pressure situations in training - simulate 11-11 scenarios</p></details><hr><h2 id="ressources-connexes" tabindex="-1">Ressources connexes <a class="header-anchor" href="#ressources-connexes" aria-label="Permalink to &quot;Ressources connexes&quot;">​</a></h2><ul><li><a href="/en/goal-template">Modèle de définition d&#39;objectifs</a> - Définissez et suivez vos objectifs d&#39;amélioration</li><li><a href="/en/workshop">Atelier</a> - Séances de groupe sur le mental et la réflexion</li><li><a href="/en/training-session">Séance de formation</a> - Pratique structurée avec des pairs</li><li><a href="/en/education/mental-strength">Force mentale</a> - Développer sa résilience mentale</li><li><a href="/en/education/mindfulness">Pleine conscience</a> - Développer la conscience et la concentration</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to diary keeping? Start here:</strong></p><p><strong>Week 1:</strong> Use Quick Daily Entry (5 minutes after each session) <strong>Week 2:</strong> Add one reflection prompt per entry <strong>Week 3:</strong> Try full Daily Training Entry <strong>Week 4:</strong> Do first Weekly Summary</p><p><strong>After one month:</strong> Add Monthly Summary and specific practice logs</p><hr><p>::: warning : Erreurs courantes dans un journal intime</p><ol><li><strong>Trop détaillé</strong> - Je passe 30 minutes à écrire, puis j&#39;abandonne au bout d&#39;une semaine.</li><li><strong>Trop vague</strong> - « Entraînement aujourd&#39;hui, ça s&#39;est bien passé » ne vous aide pas à progresser.</li><li><strong>N&#39;enregistrez que les échecs</strong> - Célébrez aussi les victoires !</li><li><strong>Ne jamais relire</strong> - La clé du succès réside dans la lecture des articles précédents.</li><li><strong>Attendre trop longtemps</strong> - Écrire dans les 30 minutes suivant la fin :::</li></ol><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Evernote</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Daily Training Entry Template</li><li>Competition/Match Entry Template</li><li>Weekly Summary Template</li></ol><hr><p><strong>Meilleur moment :</strong></p><p><strong>Moment le plus difficile :</strong></p><p><strong>Ma réponse :</strong></p><hr><h3 id="mental-game-in-competition" tabindex="-1">Mental Game in Competition <a class="header-anchor" href="#mental-game-in-competition" aria-label="Permalink to &quot;Mental Game in Competition&quot;">​</a></h3><p><strong>Pressure Situations:</strong></p><p><strong>How I Managed Pressure:</strong></p><p><strong>Inner Critic Activity (1-10):</strong> _____ <strong>Inner Coach Activity (1-10):</strong> _____</p><p><strong>Mental Techniques Used:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Routine Consistency</li><li>[ ] Other: ________</li></ul><hr><h3 id="principaux-enseignements" tabindex="-1">Principaux enseignements <a class="header-anchor" href="#principaux-enseignements" aria-label="Permalink to &quot;Principaux enseignements&quot;">​</a></h3><p><strong>Technique:</strong></p><p><strong>Tactique:</strong></p><p><strong>Mental:</strong></p><p><strong>Pour le prochain concours :</strong></p><hr><h2 id="weekly-summary-template" tabindex="-1">Weekly Summary Template <a class="header-anchor" href="#weekly-summary-template" aria-label="Permalink to &quot;Weekly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Semaine du :</strong> ________</p><h3 id="apercu-de-la-formation" tabindex="-1">Aperçu de la formation <a class="header-anchor" href="#apercu-de-la-formation" aria-label="Permalink to &quot;Aperçu de la formation&quot;">​</a></h3><p><strong>Nombre total d&#39;heures de formation :</strong> _____ <strong>Nombre de séances :</strong> _____ <strong>Heures de compétition :</strong> _____ <strong>Entraînement mental :</strong> _____ minutes <strong>Entraînement physique :</strong> _____ séances</p><h3 id="progression-hebdomadaire" tabindex="-1">Progression hebdomadaire <a class="header-anchor" href="#progression-hebdomadaire" aria-label="Permalink to &quot;Progression hebdomadaire&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Domaine d&#39;intervention</th><th>Cible</th><th>Réalisé</th><th>Progression</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="victoires-de-cette-semaine" tabindex="-1">Victoires de cette semaine <a class="header-anchor" href="#victoires-de-cette-semaine" aria-label="Permalink to &quot;Victoires de cette semaine&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="les-defis-de-cette-semaine" tabindex="-1">Les défis de cette semaine <a class="header-anchor" href="#les-defis-de-cette-semaine" aria-label="Permalink to &quot;Les défis de cette semaine&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="reconnaissance-de-formes" tabindex="-1">Reconnaissance de formes <a class="header-anchor" href="#reconnaissance-de-formes" aria-label="Permalink to &quot;Reconnaissance de formes&quot;">​</a></h3><p>(Quelles tendances observe-je dans ma pratique/mes performances ?)</p><h3 id="theme-de-la-semaine-prochaine" tabindex="-1">Thème de la semaine prochaine <a class="header-anchor" href="#theme-de-la-semaine-prochaine" aria-label="Permalink to &quot;Thème de la semaine prochaine&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr>',196)])])}]]);export{r as __pageData,o as default};
